first = boundary retry 3 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 3 { return list_orders({ month: "2026-03", page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
orders = fold acc = first.items for page in remaining { return acc + page }

details = for o in orders {
    ord = boundary retry 3 { return get_order({ id: o.id }) } catch err {
        return fail("GET_ORDER_FAILED", err.code + ": " + err.message)
    }
    skip if ord.status != "completed"
    cust = boundary retry 3 { return get_customer({ id: o.customer_id }) } catch err {
        return fail("GET_CUSTOMER_FAILED", err.code + ": " + err.message)
    }
    return { region: cust.region, amount_cents: ord.amount_cents }
}

totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for d in details {
    return acc + { [d.region]: acc[d.region] + d.amount_cents }
}

submitted = submit_result({ answer: totals })
return { totals, submitted }

